package com.example.myapplication.data.algorithm

/**
 * Supported programming languages in AlgoQuest Code Visualizer
 */
enum class CodeLanguage(val displayName: String, val extension: String) {
    KOTLIN("Kotlin", "kt"),
    PYTHON("Python", "py"),
    JAVA("Java", "java")
}

/**
 * Represents a single execution frame generated by the execution engine.
 */
data class ExecutionFrame(
    val stepIndex: Int,
    val arraySnapshot: List<Int>,
    val pointer1: Int = -1, // e.g. low (BS), j (Bubble), left (Two Pointers)
    val pointer2: Int = -1, // e.g. high (BS), j+1 (Bubble), right (Two Pointers)
    val pointer3: Int = -1, // e.g. mid (BS)
    val pointerLabels: Map<Int, String> = emptyMap(),
    val activeLineNumber: Int, // 1-based line number in the current code editor
    val activeLineCode: String = "",
    val description: String,
    val reason: String = "",
    val variables: Map<String, String> = emptyMap(),
    val comparisonsCount: Int = 0,
    val swapsCount: Int = 0,
    val isFound: Boolean = false,
    val isSwap: Boolean = false,
    val eliminatedIndices: Set<Int> = emptySet(),
    val isCompleted: Boolean = false,
    val returnValue: String? = null
)

/**
 * Code template definition with metadata and default source code per language.
 */
data class AlgorithmCodeTemplate(
    val algorithmType: AlgorithmType,
    val language: CodeLanguage,
    val defaultCode: String,
    val lineMapping: Map<String, Int> // semantic event name -> 1-based line number
)

/**
 * Stores and manages algorithm templates for Kotlin, Python, and Java.
 */
object CodeTemplateRegistry {

    fun getTemplate(type: AlgorithmType, language: CodeLanguage): AlgorithmCodeTemplate {
        return when (type) {
            AlgorithmType.BINARY_SEARCH -> when (language) {
                CodeLanguage.KOTLIN -> AlgorithmCodeTemplate(
                    algorithmType = type,
                    language = language,
                    defaultCode = """
fun binarySearch(arr: IntArray, target: Int): Int {
    var low = 0
    var high = arr.size - 1
    while (low <= high) {
        val mid = low + (high - low) / 2
        if (arr[mid] == target) {
            return mid
        } else if (arr[mid] < target) {
            low = mid + 1
        } else {
            high = mid - 1
        }
    }
    return -1
}
                    """.trimIndent(),
                    lineMapping = mapOf(
                        "init" to 2,
                        "loop_check" to 4,
                        "calc_mid" to 5,
                        "compare" to 6,
                        "found" to 7,
                        "narrow_right" to 9,
                        "narrow_left" to 11,
                        "not_found" to 14
                    )
                )

                CodeLanguage.PYTHON -> AlgorithmCodeTemplate(
                    algorithmType = type,
                    language = language,
                    defaultCode = """
def binary_search(arr, target):
    low = 0
    high = len(arr) - 1
    while low <= high:
        mid = low + (high - low) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
                    """.trimIndent(),
                    lineMapping = mapOf(
                        "init" to 2,
                        "loop_check" to 4,
                        "calc_mid" to 5,
                        "compare" to 6,
                        "found" to 7,
                        "narrow_right" to 9,
                        "narrow_left" to 11,
                        "not_found" to 12
                    )
                )

                CodeLanguage.JAVA -> AlgorithmCodeTemplate(
                    algorithmType = type,
                    language = language,
                    defaultCode = """
public static int binarySearch(int[] arr, int target) {
    int low = 0;
    int high = arr.length - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (arr[mid] == target) {
            return mid;
        } else if (arr[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}
                    """.trimIndent(),
                    lineMapping = mapOf(
                        "init" to 2,
                        "loop_check" to 4,
                        "calc_mid" to 5,
                        "compare" to 6,
                        "found" to 7,
                        "narrow_right" to 9,
                        "narrow_left" to 11,
                        "not_found" to 14
                    )
                )
            }

            AlgorithmType.BUBBLE_SORT -> when (language) {
                CodeLanguage.KOTLIN -> AlgorithmCodeTemplate(
                    algorithmType = type,
                    language = language,
                    defaultCode = """
fun bubbleSort(arr: IntArray) {
    val n = arr.size
    for (i in 0 until n - 1) {
        var swapped = false
        for (j in 0 until n - i - 1) {
            if (arr[j] > arr[j + 1]) {
                val temp = arr[j]
                arr[j] = arr[j + 1]
                arr[j + 1] = temp
                swapped = true
            }
        }
        if (!swapped) break
    }
}
                    """.trimIndent(),
                    lineMapping = mapOf(
                        "init" to 2,
                        "outer_loop" to 3,
                        "inner_loop" to 5,
                        "compare" to 6,
                        "swap" to 7,
                        "settled" to 13,
                        "complete" to 15
                    )
                )

                CodeLanguage.PYTHON -> AlgorithmCodeTemplate(
                    algorithmType = type,
                    language = language,
                    defaultCode = """
def bubble_sort(arr):
    n = len(arr)
    for i in range(n - 1):
        swapped = False
        for j in range(n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
                swapped = True
        if not swapped:
            break
    return arr
                    """.trimIndent(),
                    lineMapping = mapOf(
                        "init" to 2,
                        "outer_loop" to 3,
                        "inner_loop" to 5,
                        "compare" to 6,
                        "swap" to 7,
                        "settled" to 9,
                        "complete" to 11
                    )
                )

                CodeLanguage.JAVA -> AlgorithmCodeTemplate(
                    algorithmType = type,
                    language = language,
                    defaultCode = """
public static void bubbleSort(int[] arr) {
    int n = arr.length;
    for (int i = 0; i < n - 1; i++) {
        boolean swapped = false;
        for (int j = 0; j < n - i - 1; j++) {
            if (arr[j] > arr[j + 1]) {
                int temp = arr[j];
                arr[j] = arr[j + 1];
                arr[j + 1] = temp;
                swapped = true;
            }
        }
        if (!swapped) break;
    }
}
                    """.trimIndent(),
                    lineMapping = mapOf(
                        "init" to 2,
                        "outer_loop" to 3,
                        "inner_loop" to 5,
                        "compare" to 6,
                        "swap" to 7,
                        "settled" to 13,
                        "complete" to 15
                    )
                )
            }

            AlgorithmType.TWO_POINTERS -> when (language) {
                CodeLanguage.KOTLIN -> AlgorithmCodeTemplate(
                    algorithmType = type,
                    language = language,
                    defaultCode = """
fun twoSumSorted(arr: IntArray, target: Int): Pair<Int, Int>? {
    var left = 0
    var right = arr.size - 1
    while (left < right) {
        val sum = arr[left] + arr[right]
        if (sum == target) {
            return Pair(left, right)
        } else if (sum < target) {
            left++
        } else {
            right--
        }
    }
    return null
}
                    """.trimIndent(),
                    lineMapping = mapOf(
                        "init" to 2,
                        "loop_check" to 4,
                        "calc_sum" to 5,
                        "check_match" to 6,
                        "found" to 7,
                        "move_left" to 9,
                        "move_right" to 11,
                        "not_found" to 14
                    )
                )

                CodeLanguage.PYTHON -> AlgorithmCodeTemplate(
                    algorithmType = type,
                    language = language,
                    defaultCode = """
def two_sum_sorted(arr, target):
    left = 0
    right = len(arr) - 1
    while left < right:
        curr_sum = arr[left] + arr[right]
        if curr_sum == target:
            return (left, right)
        elif curr_sum < target:
            left += 1
        else:
            right -= 1
    return None
                    """.trimIndent(),
                    lineMapping = mapOf(
                        "init" to 2,
                        "loop_check" to 4,
                        "calc_sum" to 5,
                        "check_match" to 6,
                        "found" to 7,
                        "move_left" to 9,
                        "move_right" to 11,
                        "not_found" to 12
                    )
                )

                CodeLanguage.JAVA -> AlgorithmCodeTemplate(
                    algorithmType = type,
                    language = language,
                    defaultCode = """
public static int[] twoSumSorted(int[] arr, int target) {
    int left = 0;
    int right = arr.length - 1;
    while (left < right) {
        int sum = arr[left] + arr[right];
        if (sum == target) {
            return new int[]{left, right};
        } else if (sum < target) {
            left++;
        } else {
            right--;
        }
    }
    return null;
}
                    """.trimIndent(),
                    lineMapping = mapOf(
                        "init" to 2,
                        "loop_check" to 4,
                        "calc_sum" to 5,
                        "check_match" to 6,
                        "found" to 7,
                        "move_left" to 9,
                        "move_right" to 11,
                        "not_found" to 14
                    )
                )
            }
        }
    }
}

/**
 * Result of validating user-edited code in the code editor.
 */
sealed class CodeValidationResult {
    data class Valid(
        val isCustomDescendingSort: Boolean = false,
        val customNotes: String = ""
    ) : CodeValidationResult()

    data class Warning(
        val message: String,
        val fallbackNotes: String
    ) : CodeValidationResult()
}

/**
 * Validates user-edited code against algorithmic requirements safely.
 */
object CodeValidator {

    fun validateCode(
        code: String,
        algorithmType: AlgorithmType,
        language: CodeLanguage
    ): CodeValidationResult {
        if (code.isBlank()) {
            return CodeValidationResult.Warning(
                "Code editor is empty. Loaded standard canonical template.",
                "Using default template."
            )
        }

        // Check if user changed sort direction in Bubble Sort
        if (algorithmType == AlgorithmType.BUBBLE_SORT) {
            val hasDescending = code.contains("arr[j] < arr[j + 1]") || code.contains("arr[j] < arr[j+1]")
            if (hasDescending) {
                return CodeValidationResult.Valid(
                    isCustomDescendingSort = true,
                    customNotes = "Detected descending order condition (arr[j] < arr[j+1]). Visualizing descending sort!"
                )
            }
        }

        // Structural check
        val containsEssentialKeyword = when (algorithmType) {
            AlgorithmType.BINARY_SEARCH -> code.contains("mid") || code.contains("low")
            AlgorithmType.BUBBLE_SORT -> code.contains("swap") || code.contains("temp") || code.contains("swapped")
            AlgorithmType.TWO_POINTERS -> code.contains("left") || code.contains("right") || code.contains("sum")
        }

        if (!containsEssentialKeyword) {
            return CodeValidationResult.Warning(
                "Notice: Custom code does not match standard ${algorithmType.displayName} invariants. Running canonical algorithm runner.",
                "Arbitrary code AST evaluation is protected for mobile runtime safety."
            )
        }

        return CodeValidationResult.Valid(isCustomDescendingSort = false)
    }
}

/**
 * Execution Engine generating real execution traces mapped to the user's selected code language.
 */
object ExecutionEngine {

    fun generateTrace(
        algorithmType: AlgorithmType,
        language: CodeLanguage,
        userCode: String,
        array: List<Int>,
        target: Int?
    ): List<ExecutionFrame> {
        val template = CodeTemplateRegistry.getTemplate(algorithmType, language)
        val codeLines = userCode.lines()
        val lineMap = template.lineMapping

        fun getLine(key: String, fallback: Int = 1): Int {
            return lineMap[key]?.coerceIn(1, codeLines.size.coerceAtLeast(1)) ?: fallback
        }

        fun getCodeText(lineNum: Int): String {
            return codeLines.getOrElse(lineNum - 1) { "" }.trim()
        }

        val validation = CodeValidator.validateCode(userCode, algorithmType, language)
        val isDescending = validation is CodeValidationResult.Valid && validation.isCustomDescendingSort

        return when (algorithmType) {
            AlgorithmType.BINARY_SEARCH -> {
                generateBinarySearchTrace(array, target ?: 0, ::getLine, ::getCodeText)
            }
            AlgorithmType.BUBBLE_SORT -> {
                generateBubbleSortTrace(array, isDescending, ::getLine, ::getCodeText)
            }
            AlgorithmType.TWO_POINTERS -> {
                generateTwoPointersTrace(array, target ?: 0, ::getLine, ::getCodeText)
            }
        }
    }

    private fun generateBinarySearchTrace(
        array: List<Int>,
        target: Int,
        getLine: (String) -> Int,
        getCode: (Int) -> String
    ): List<ExecutionFrame> {
        val frames = mutableListOf<ExecutionFrame>()
        val arr = array.toList()
        val n = arr.size
        if (n == 0) return emptyList()

        var low = 0
        var high = n - 1
        var comparisons = 0
        var step = 1
        val eliminated = mutableSetOf<Int>()

        // 1. Initialization
        val initLine = getLine("init")
        frames.add(
            ExecutionFrame(
                stepIndex = step++,
                arraySnapshot = arr,
                pointer1 = low,
                pointer2 = high,
                pointerLabels = mapOf(low to "L", high to "H"),
                activeLineNumber = initLine,
                activeLineCode = getCode(initLine),
                description = "Initialized: low = $low, high = $high, target = $target. Search space: [0..${n - 1}].",
                reason = "Pointers initialized to array bounds.",
                variables = mapOf("low" to "$low", "high" to "$high", "target" to "$target"),
                comparisonsCount = 0
            )
        )

        var foundIndex = -1

        while (low <= high) {
            val loopLine = getLine("loop_check")
            frames.add(
                ExecutionFrame(
                    stepIndex = step++,
                    arraySnapshot = arr,
                    pointer1 = low,
                    pointer2 = high,
                    pointerLabels = mapOf(low to "L", high to "H"),
                    activeLineNumber = loopLine,
                    activeLineCode = getCode(loopLine),
                    description = "Boundary check: low ($low) <= high ($high) is true. Search interval active.",
                    reason = "Loop continues as long as search space contains at least one candidate.",
                    variables = mapOf("low" to "$low", "high" to "$high", "condition" to "$low <= $high"),
                    eliminatedIndices = eliminated.toSet(),
                    comparisonsCount = comparisons
                )
            )

            val mid = low + (high - low) / 2
            val midVal = arr[mid]
            val calcMidLine = getLine("calc_mid")

            val labelsWithMid = mutableMapOf<Int, String>()
            if (low == high && low == mid) {
                labelsWithMid[low] = "L M H"
            } else {
                if (low == mid) labelsWithMid[low] = "L M" else labelsWithMid[low] = "L"
                if (high == mid) labelsWithMid[high] = "M H" else labelsWithMid[high] = "H"
                if (mid != low && mid != high) labelsWithMid[mid] = "M"
            }

            frames.add(
                ExecutionFrame(
                    stepIndex = step++,
                    arraySnapshot = arr,
                    pointer1 = low,
                    pointer2 = high,
                    pointer3 = mid,
                    pointerLabels = labelsWithMid,
                    activeLineNumber = calcMidLine,
                    activeLineCode = getCode(calcMidLine),
                    description = "Computed midpoint: mid = $low + ($high - $low) / 2 = $mid (value: $midVal).",
                    reason = "Integer-overflow safe calculation bisects search interval.",
                    variables = mapOf("low" to "$low", "mid" to "$mid", "high" to "$high", "arr[mid]" to "$midVal", "target" to "$target"),
                    eliminatedIndices = eliminated.toSet(),
                    comparisonsCount = comparisons
                )
            )

            // Comparison
            comparisons++
            val compareLine = getLine("compare")

            if (midVal == target) {
                foundIndex = mid
                val foundLine = getLine("found")
                frames.add(
                    ExecutionFrame(
                        stepIndex = step++,
                        arraySnapshot = arr,
                        pointer1 = low,
                        pointer2 = high,
                        pointer3 = mid,
                        pointerLabels = mapOf(mid to "FOUND!"),
                        activeLineNumber = foundLine,
                        activeLineCode = getCode(foundLine),
                        description = "Target found! arr[$mid] ($midVal) == Target ($target). Returning index $mid.",
                        reason = "Match identified. Terminating search.",
                        variables = mapOf("mid" to "$mid", "arr[mid]" to "$midVal", "result" to "Index $mid"),
                        isFound = true,
                        isCompleted = true,
                        eliminatedIndices = eliminated.toSet(),
                        comparisonsCount = comparisons,
                        returnValue = "Index $mid"
                    )
                )
                break
            } else if (midVal < target) {
                for (i in low..mid) {
                    eliminated.add(i)
                }
                val narrowRightLine = getLine("narrow_right")
                val newLow = mid + 1
                frames.add(
                    ExecutionFrame(
                        stepIndex = step++,
                        arraySnapshot = arr,
                        pointer1 = low,
                        pointer2 = high,
                        pointer3 = mid,
                        pointerLabels = labelsWithMid,
                        activeLineNumber = narrowRightLine,
                        activeLineCode = getCode(narrowRightLine),
                        description = "arr[$mid] ($midVal) < Target ($target): Target lies strictly to the right. Discard [${low}..${mid}].",
                        reason = "Monotonic ordering guarantees all elements <= arr[mid] are too small.",
                        variables = mapOf("low" to "$low", "mid" to "$mid", "high" to "$high", "new_low" to "$newLow"),
                        eliminatedIndices = eliminated.toSet(),
                        comparisonsCount = comparisons
                    )
                )
                low = newLow
            } else {
                for (i in mid..high) {
                    eliminated.add(i)
                }
                val narrowLeftLine = getLine("narrow_left")
                val newHigh = mid - 1
                frames.add(
                    ExecutionFrame(
                        stepIndex = step++,
                        arraySnapshot = arr,
                        pointer1 = low,
                        pointer2 = high,
                        pointer3 = mid,
                        pointerLabels = labelsWithMid,
                        activeLineNumber = narrowLeftLine,
                        activeLineCode = getCode(narrowLeftLine),
                        description = "arr[$mid] ($midVal) > Target ($target): Target lies strictly to the left. Discard [${mid}..${high}].",
                        reason = "Monotonic ordering guarantees all elements >= arr[mid] are too large.",
                        variables = mapOf("low" to "$low", "mid" to "$mid", "high" to "$high", "new_high" to "$newHigh"),
                        eliminatedIndices = eliminated.toSet(),
                        comparisonsCount = comparisons
                    )
                )
                high = newHigh
            }
        }

        if (foundIndex == -1) {
            (0 until n).forEach { eliminated.add(it) }
            val notFoundLine = getLine("not_found")
            frames.add(
                ExecutionFrame(
                    stepIndex = step++,
                    arraySnapshot = arr,
                    pointer1 = -1,
                    pointer2 = -1,
                    pointer3 = -1,
                    pointerLabels = emptyMap(),
                    activeLineNumber = notFoundLine,
                    activeLineCode = getCode(notFoundLine),
                    description = "Search interval exhausted ($low > $high). Target $target not found in array. Returning -1.",
                    reason = "All candidates eliminated without match.",
                    variables = mapOf("low" to "$low", "high" to "$high", "result" to "-1"),
                    isFound = false,
                    isCompleted = true,
                    eliminatedIndices = eliminated.toSet(),
                    comparisonsCount = comparisons,
                    returnValue = "-1 (Not Found)"
                )
            )
        }

        return frames
    }

    private fun generateBubbleSortTrace(
        array: List<Int>,
        isDescending: Boolean,
        getLine: (String) -> Int,
        getCode: (Int) -> String
    ): List<ExecutionFrame> {
        val frames = mutableListOf<ExecutionFrame>()
        val arr = array.toMutableList()
        val n = arr.size
        if (n == 0) return emptyList()

        var step = 1
        var comparisons = 0
        var totalSwaps = 0
        val sortedIndices = mutableSetOf<Int>()

        // 1. Init
        val initLine = getLine("init")
        frames.add(
            ExecutionFrame(
                stepIndex = step++,
                arraySnapshot = arr.toList(),
                activeLineNumber = initLine,
                activeLineCode = getCode(initLine),
                description = "Bubble Sort initialized. Array length = $n. Mode: ${if (isDescending) "Descending" else "Ascending"}.",
                reason = "Ready to start comparison passes.",
                variables = mapOf("n" to "$n", "swaps" to "0", "comparisons" to "0")
            )
        )

        for (i in 0 until n - 1) {
            var swappedInPass = false
            val outerLine = getLine("outer_loop")

            frames.add(
                ExecutionFrame(
                    stepIndex = step++,
                    arraySnapshot = arr.toList(),
                    activeLineNumber = outerLine,
                    activeLineCode = getCode(outerLine),
                    description = "Pass ${i + 1} started. Elements already in final position: $sortedIndices.",
                    reason = "Pass i bubbles the i-th boundary element to its settled location.",
                    variables = mapOf("pass" to "${i + 1}", "unsorted_bound" to "${n - 1 - i}")
                )
            )

            for (j in 0 until n - i - 1) {
                comparisons++
                val labels = mutableMapOf<Int, String>()
                labels[j] = "j"
                labels[j + 1] = "j+1"
                sortedIndices.forEach { labels[it] = "Sorted" }

                val shouldSwap = if (isDescending) arr[j] < arr[j + 1] else arr[j] > arr[j + 1]
                val compareLine = getLine("compare")

                frames.add(
                    ExecutionFrame(
                        stepIndex = step++,
                        arraySnapshot = arr.toList(),
                        pointer1 = j,
                        pointer2 = j + 1,
                        pointerLabels = labels,
                        activeLineNumber = compareLine,
                        activeLineCode = getCode(compareLine),
                        description = "Comparing arr[$j] (${arr[j]}) and arr[${j + 1}] (${arr[j + 1]}): " +
                                if (shouldSwap) "Out of order -> Will swap!" else "In order -> No swap.",
                        reason = "Adjacent pair inspection.",
                        variables = mapOf("pass" to "${i + 1}", "j" to "$j", "arr[j]" to "${arr[j]}", "arr[j+1]" to "${arr[j + 1]}"),
                        comparisonsCount = comparisons,
                        swapsCount = totalSwaps
                    )
                )

                if (shouldSwap) {
                    val temp = arr[j]
                    arr[j] = arr[j + 1]
                    arr[j + 1] = temp
                    swappedInPass = true
                    totalSwaps++

                    val swapLabels = mutableMapOf<Int, String>()
                    swapLabels[j] = "Swapped"
                    swapLabels[j + 1] = "Swapped"
                    sortedIndices.forEach { swapLabels[it] = "Sorted" }

                    val swapLine = getLine("swap")
                    frames.add(
                        ExecutionFrame(
                            stepIndex = step++,
                            arraySnapshot = arr.toList(),
                            pointer1 = j,
                            pointer2 = j + 1,
                            pointerLabels = swapLabels,
                            activeLineNumber = swapLine,
                            activeLineCode = getCode(swapLine),
                            description = "Swapped arr[$j] and arr[${j + 1}]. New values: [${arr[j]}, ${arr[j + 1]}]. Total swaps: $totalSwaps.",
                            reason = "Inversion resolved; element moves closer to sorted position.",
                            variables = mapOf("pass" to "${i + 1}", "swapped" to "true", "total_swaps" to "$totalSwaps"),
                            comparisonsCount = comparisons,
                            swapsCount = totalSwaps,
                            isSwap = true
                        )
                    )
                }
            }

            val settledIndex = n - 1 - i
            sortedIndices.add(settledIndex)
            val settledLabels = mutableMapOf<Int, String>()
            sortedIndices.forEach { settledLabels[it] = "Sorted" }

            val settledLine = getLine("settled")
            frames.add(
                ExecutionFrame(
                    stepIndex = step++,
                    arraySnapshot = arr.toList(),
                    pointer1 = settledIndex,
                    pointerLabels = settledLabels,
                    activeLineNumber = settledLine,
                    activeLineCode = getCode(settledLine),
                    description = "Pass ${i + 1} finished. Element at index $settledIndex (${arr[settledIndex]}) is now permanently sorted.",
                    reason = "Invariant: Suffix array is sorted after each pass.",
                    variables = mapOf("pass" to "${i + 1}", "settled_index" to "$settledIndex", "value" to "${arr[settledIndex]}"),
                    comparisonsCount = comparisons,
                    swapsCount = totalSwaps,
                    isFound = true
                )
            )

            if (!swappedInPass) {
                (0 until n).forEach { sortedIndices.add(it) }
                break
            }
        }

        (0 until n).forEach { sortedIndices.add(it) }
        val finalLabels = sortedIndices.associateWith { "Sorted" }
        val completeLine = getLine("complete")

        frames.add(
            ExecutionFrame(
                stepIndex = step++,
                arraySnapshot = arr.toList(),
                pointerLabels = finalLabels,
                activeLineNumber = completeLine,
                activeLineCode = getCode(completeLine),
                description = "Sorting complete! Array sorted in $totalSwaps total swaps and $comparisons comparisons.",
                reason = "All adjacent inversions resolved.",
                variables = mapOf("total_comparisons" to "$comparisons", "total_swaps" to "$totalSwaps"),
                comparisonsCount = comparisons,
                swapsCount = totalSwaps,
                isFound = true,
                isCompleted = true,
                returnValue = arr.toString()
            )
        )

        return frames
    }

    private fun generateTwoPointersTrace(
        array: List<Int>,
        target: Int,
        getLine: (String) -> Int,
        getCode: (Int) -> String
    ): List<ExecutionFrame> {
        val frames = mutableListOf<ExecutionFrame>()
        val arr = array.toList()
        val n = arr.size
        if (n < 2) return emptyList()

        var step = 1
        var comparisons = 0
        var left = 0
        var right = n - 1
        val eliminated = mutableSetOf<Int>()

        val initLine = getLine("init")
        frames.add(
            ExecutionFrame(
                stepIndex = step++,
                arraySnapshot = arr,
                pointer1 = left,
                pointer2 = right,
                pointerLabels = mapOf(left to "L", right to "R"),
                activeLineNumber = initLine,
                activeLineCode = getCode(initLine),
                description = "Two Pointers initialized: left = $left (${arr[left]}), right = $right (${arr[right]}). Target Sum = $target.",
                reason = "Opposite-end pointers bound search space on sorted collection.",
                variables = mapOf("left" to "$left", "right" to "$right", "targetSum" to "$target")
            )
        )

        var found = false

        while (left < right) {
            val loopLine = getLine("loop_check")
            frames.add(
                ExecutionFrame(
                    stepIndex = step++,
                    arraySnapshot = arr,
                    pointer1 = left,
                    pointer2 = right,
                    pointerLabels = mapOf(left to "L", right to "R"),
                    activeLineNumber = loopLine,
                    activeLineCode = getCode(loopLine),
                    description = "Pointer check: left ($left) < right ($right). Valid candidate pair exists.",
                    reason = "Loop terminates when pointers meet.",
                    variables = mapOf("left" to "$left", "right" to "$right", "condition" to "$left < $right"),
                    eliminatedIndices = eliminated.toSet(),
                    comparisonsCount = comparisons
                )
            )

            val sum = arr[left] + arr[right]
            comparisons++
            val sumLine = getLine("calc_sum")

            frames.add(
                ExecutionFrame(
                    stepIndex = step++,
                    arraySnapshot = arr,
                    pointer1 = left,
                    pointer2 = right,
                    pointerLabels = mapOf(left to "L", right to "R"),
                    activeLineNumber = sumLine,
                    activeLineCode = getCode(sumLine),
                    description = "Sum evaluation: arr[$left] (${arr[left]}) + arr[$right] (${arr[right]}) = $sum.",
                    reason = "Pair sum calculated to compare with target $target.",
                    variables = mapOf("left" to "$left", "right" to "$right", "sum" to "$sum", "target" to "$target"),
                    eliminatedIndices = eliminated.toSet(),
                    comparisonsCount = comparisons
                )
            )

            if (sum == target) {
                found = true
                val foundLine = getLine("found")
                frames.add(
                    ExecutionFrame(
                        stepIndex = step++,
                        arraySnapshot = arr,
                        pointer1 = left,
                        pointer2 = right,
                        pointerLabels = mapOf(left to "MATCH", right to "MATCH"),
                        activeLineNumber = foundLine,
                        activeLineCode = getCode(foundLine),
                        description = "Target sum match found! arr[$left] (${arr[left]}) + arr[$right] (${arr[right]}) == $target. Returning Pair($left, $right).",
                        reason = "Target satisfied. Terminating scan.",
                        variables = mapOf("left" to "$left", "right" to "$right", "result" to "Pair($left, $right)"),
                        isFound = true,
                        isCompleted = true,
                        eliminatedIndices = eliminated.toSet(),
                        comparisonsCount = comparisons,
                        returnValue = "Pair($left, $right)"
                    )
                )
                break
            } else if (sum < target) {
                eliminated.add(left)
                val newLeft = left + 1
                val moveLeftLine = getLine("move_left")
                frames.add(
                    ExecutionFrame(
                        stepIndex = step++,
                        arraySnapshot = arr,
                        pointer1 = left,
                        pointer2 = right,
                        pointerLabels = mapOf(left to "L", right to "R"),
                        activeLineNumber = moveLeftLine,
                        activeLineCode = getCode(moveLeftLine),
                        description = "Sum ($sum) < Target ($target): Sum too small. Advance left pointer: left = $newLeft (${arr[newLeft]}).",
                        reason = "In a sorted array, arr[left] paired with any value <= arr[right] will also be < target.",
                        variables = mapOf("left" to "$left", "right" to "$right", "sum" to "$sum", "new_left" to "$newLeft"),
                        eliminatedIndices = eliminated.toSet(),
                        comparisonsCount = comparisons
                    )
                )
                left = newLeft
            } else {
                eliminated.add(right)
                val newRight = right - 1
                val moveRightLine = getLine("move_right")
                frames.add(
                    ExecutionFrame(
                        stepIndex = step++,
                        arraySnapshot = arr,
                        pointer1 = left,
                        pointer2 = right,
                        pointerLabels = mapOf(left to "L", right to "R"),
                        activeLineNumber = moveRightLine,
                        activeLineCode = getCode(moveRightLine),
                        description = "Sum ($sum) > Target ($target): Sum too large. Retreat right pointer: right = $newRight (${arr[newRight]}).",
                        reason = "In a sorted array, arr[right] paired with any value >= arr[left] will also be > target.",
                        variables = mapOf("left" to "$left", "right" to "$right", "sum" to "$sum", "new_right" to "$newRight"),
                        eliminatedIndices = eliminated.toSet(),
                        comparisonsCount = comparisons
                    )
                )
                right = newRight
            }
        }

        if (!found) {
            (0 until n).forEach { eliminated.add(it) }
            val notFoundLine = getLine("not_found")
            frames.add(
                ExecutionFrame(
                    stepIndex = step++,
                    arraySnapshot = arr,
                    pointer1 = -1,
                    pointer2 = -1,
                    activeLineNumber = notFoundLine,
                    activeLineCode = getCode(notFoundLine),
                    description = "Pointers crossed ($left >= $right). No pair in array sums to $target. Returning null.",
                    reason = "Search space exhausted in O(N) single pass.",
                    variables = mapOf("left" to "$left", "right" to "$right", "result" to "null"),
                    isFound = false,
                    isCompleted = true,
                    eliminatedIndices = eliminated.toSet(),
                    comparisonsCount = comparisons,
                    returnValue = "null (Not Found)"
                )
            )
        }

        return frames
    }
}

